"use strict";(globalThis.webpackChunkdocs=globalThis.webpackChunkdocs||[]).push([[849],{6164:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/docs/intro","label":"Getting Started","docId":"intro","unlisted":false},{"type":"link","href":"/docs/authentication","label":"Authentication","docId":"authentication","unlisted":false},{"type":"category","label":"Entities","items":[{"type":"category","label":"Lighting & Power","items":[{"type":"link","href":"/docs/entities/light","label":"Light","docId":"entities/light","unlisted":false},{"type":"link","href":"/docs/entities/switch","label":"Switch","docId":"entities/switch","unlisted":false},{"type":"link","href":"/docs/entities/fan","label":"Fan","docId":"entities/fan","unlisted":false},{"type":"link","href":"/docs/entities/scene","label":"Scene","docId":"entities/scene","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Climate & Environment","items":[{"type":"link","href":"/docs/entities/climate","label":"Climate","docId":"entities/climate","unlisted":false},{"type":"link","href":"/docs/entities/weather","label":"Weather","docId":"entities/weather","unlisted":false},{"type":"link","href":"/docs/entities/sensor","label":"Sensor","docId":"entities/sensor","unlisted":false},{"type":"link","href":"/docs/entities/binary-sensor","label":"Binary Sensor","docId":"entities/binary-sensor","unlisted":false},{"type":"link","href":"/docs/entities/number","label":"Number","docId":"entities/number","unlisted":false},{"type":"link","href":"/docs/entities/datetime","label":"DateTime","docId":"entities/datetime","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Security & Access","items":[{"type":"link","href":"/docs/entities/alarm-control-panel","label":"Alarm Control Panel","docId":"entities/alarm-control-panel","unlisted":false},{"type":"link","href":"/docs/entities/camera","label":"Camera","docId":"entities/camera","unlisted":false},{"type":"link","href":"/docs/entities/lock","label":"Lock","docId":"entities/lock","unlisted":false},{"type":"link","href":"/docs/entities/cover","label":"Cover","docId":"entities/cover","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Entertainment","items":[{"type":"link","href":"/docs/entities/media-player","label":"Media Player","docId":"entities/media-player","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Productivity","items":[{"type":"link","href":"/docs/entities/calendar","label":"Calendar","docId":"entities/calendar","unlisted":false},{"type":"link","href":"/docs/entities/todo","label":"Todo","docId":"entities/todo","unlisted":false},{"type":"link","href":"/docs/entities/vacuum","label":"Vacuum","docId":"entities/vacuum","unlisted":false}],"collapsed":true,"collapsible":true}],"collapsed":true,"collapsible":true},{"type":"category","label":"Advanced Hooks","items":[{"type":"link","href":"/docs/advanced/multiple-entities","label":"Working with Multiple Entities","docId":"advanced/multiple-entities","unlisted":false},{"type":"link","href":"/docs/advanced/custom-service-calls","label":"Custom Service Calls","docId":"advanced/custom-service-calls","unlisted":false},{"type":"link","href":"/docs/advanced/external-transports","label":"External Transports","docId":"advanced/external-transports","unlisted":false},{"type":"link","href":"/docs/advanced/building-a-gateway","label":"Building a Gateway","docId":"advanced/building-a-gateway","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","href":"/docs/error-handling","label":"Error Handling & Connection Status","docId":"error-handling","unlisted":false},{"type":"link","href":"/docs/development-testing","label":"Development & Testing","docId":"development-testing","unlisted":false}]},"docs":{"advanced/building-a-gateway":{"id":"advanced/building-a-gateway","title":"Building a Gateway","description":"External Transports covers the contract hass-react expects. This page builds the other half: the gateway server that owns your Home Assistant credential, plus the browser transport that talks to it.","sidebar":"tutorialSidebar"},"advanced/custom-service-calls":{"id":"advanced/custom-service-calls","title":"Custom Service Calls","description":"Call Home Assistant services directly when the entity hooks don\'t cover what you need.","sidebar":"tutorialSidebar"},"advanced/external-transports":{"id":"advanced/external-transports","title":"External Transports","description":"Use an external transport when the browser should not authenticate directly with Home Assistant. This is useful for kiosks, wall-mounted dashboards, server-rendered applications, and backend-for-frontend architectures where a server owns the Home Assistant credentials.","sidebar":"tutorialSidebar"},"advanced/multiple-entities":{"id":"advanced/multiple-entities","title":"Working with Multiple Entities","description":"Dashboards usually need more than one entity at a time. The useEntityGroup hook subscribes to a list of entities in a single call.","sidebar":"tutorialSidebar"},"authentication":{"id":"authentication","title":"Authentication","description":"hass-react supports OAuth 2.0 and long-lived token authentication, and detects which to use based on the props you pass.","sidebar":"tutorialSidebar"},"development-testing":{"id":"development-testing","title":"Development & Testing","description":"You won\'t always have a real Home Assistant instance to point at while you build. Mock mode and the built-in development warnings cover that gap.","sidebar":"tutorialSidebar"},"entities/alarm-control-panel":{"id":"entities/alarm-control-panel","title":"Alarm Control Panel","description":"Arm and disarm security panels, watch their state, and trigger the alarm on panels that support it.","sidebar":"tutorialSidebar"},"entities/binary-sensor":{"id":"entities/binary-sensor","title":"Binary Sensor","description":"Track on/off sensors: doors and windows, motion, smoke, water leaks.","sidebar":"tutorialSidebar"},"entities/calendar":{"id":"entities/calendar","title":"Calendar","description":"Read events from Home Assistant calendars and create new ones. Update and delete are wired up too, but they\'re waiting on Home Assistant (see the warning below).","sidebar":"tutorialSidebar"},"entities/camera":{"id":"entities/camera","title":"Camera","description":"Show still images or live streams (HLS, MJPEG, or WebRTC) from your cameras.","sidebar":"tutorialSidebar"},"entities/climate":{"id":"entities/climate","title":"Climate","description":"Control thermostats and HVAC systems: target temperature, mode, fan, and presets.","sidebar":"tutorialSidebar"},"entities/cover":{"id":"entities/cover","title":"Cover","description":"Open, close, and position covers: blinds, garage doors, curtains, shades.","sidebar":"tutorialSidebar"},"entities/datetime":{"id":"entities/datetime","title":"DateTime","description":"Access Home Assistant server time as a JavaScript Date object.","sidebar":"tutorialSidebar"},"entities/fan":{"id":"entities/fan","title":"Fan","description":"Control fans: speed, preset modes, oscillation, direction.","sidebar":"tutorialSidebar"},"entities/light":{"id":"entities/light","title":"Light","description":"Control lights: on/off, brightness, color, and effects.","sidebar":"tutorialSidebar"},"entities/lock":{"id":"entities/lock","title":"Lock","description":"Lock and unlock smart locks. Locks with a latch can also be opened.","sidebar":"tutorialSidebar"},"entities/media-player":{"id":"entities/media-player","title":"Media Player","description":"Playback, volume, source selection, and track info for media player entities.","sidebar":"tutorialSidebar"},"entities/number":{"id":"entities/number","title":"Number","description":"Numeric input controls with configurable min/max/step values.","sidebar":"tutorialSidebar"},"entities/scene":{"id":"entities/scene","title":"Scene","description":"Activate scenes defined in Home Assistant. One call sets every device in the scene to its saved state.","sidebar":"tutorialSidebar"},"entities/sensor":{"id":"entities/sensor","title":"Sensor","description":"Read sensor values: temperature, humidity, power usage, anything Home Assistant reports as a sensor.","sidebar":"tutorialSidebar"},"entities/switch":{"id":"entities/switch","title":"Switch","description":"Simple on/off control for switches and plugs.","sidebar":"tutorialSidebar"},"entities/todo":{"id":"entities/todo","title":"Todo","description":"Work with Home Assistant todo lists: add items, check them off, update them, remove them.","sidebar":"tutorialSidebar"},"entities/vacuum":{"id":"entities/vacuum","title":"Vacuum","description":"Start, pause, and dock robot vacuums, and keep an eye on battery and cleaning status.","sidebar":"tutorialSidebar"},"entities/weather":{"id":"entities/weather","title":"Weather","description":"Read current conditions from Home Assistant weather integrations: temperature, humidity, wind, pressure, and more.","sidebar":"tutorialSidebar"},"error-handling":{"id":"error-handling","title":"Error Handling & Connection Status","description":"Networks drop, entities disappear, service calls fail. hass-react gives you typed errors and connection state hooks so your UI can handle all of it.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Getting Started","description":"hass-react is a headless React library that provides hooks and components for building Home Assistant user interfaces without the hassle of WebSockets or service calls.","sidebar":"tutorialSidebar"}}}}')}}]);